import { ChangeDetectionStrategy, Component, computed, inject, input } from '@angular/core';
import { TranslationService } from '../../core/i18n/translation';
import { formatTarget, TargetView } from '../game.models';

/** Random-Hit target card (template `target-info`); the target itself is generated by the server. */
@Component({
  selector: 'app-random-target',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './random-target.html',
  styleUrl: './random-target.scss',
})
export class RandomTarget {
  protected readonly i18n = inject(TranslationService);

  readonly target = input<TargetView | null>(null);
  protected readonly label = computed(() => formatTarget(this.target()));
}
